function repeat(s,n){var o='';for(var i=0;i<n;i++)o+=s;return o;}
function cowsay(text){
  text=(text==null)?'':String(text);
  var lines=text.split('\n').map(function(l){return l.slice(0,40);});
  var w=0; for(var i=0;i<lines.length;i++) w=Math.max(w,lines[i].length);
  if(w<1) w=1;
  function pad(l){while(l.length<w)l+=' ';return l;}
  var box;
  if(lines.length===1){
    box=' '+repeat('_',w+2)+'\n< '+pad(lines[0])+' >\n '+repeat('-',w+2);
  } else {
    var mid=lines.map(function(l){return '| '+pad(l)+' |';}).join('\n');
    box=' '+repeat('_',w+2)+'\n'+mid+'\n '+repeat('-',w+2);
  }
  var cow="\n        \\   ^__^\n         \\  (oo)\\_______\n            (__)\\       )\\/\\\n                ||----w |\n                ||     ||";
  return box+cow;
}
var EXPORTS={cowsay:cowsay};


if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.CowsayForgePure = EXPORTS; }
